#include <iostream>
#include <vector>
using namespace std;

using ll = long long;
const int MOD = 998244353;

ll modPow(ll a, ll b) {
    ll result = 1;
    a %= MOD;
    while (b > 0) {
        if (b & 1) result = result * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    ll m;
    cin >> n >> m;

    vector<int> inverse(n + 1);
    if (n >= 1) inverse[1] = 1;

    ll res = (m + 1) % MOD;
    ll mMod = m % MOD;

    for (int i = 2; i <= n; ++i) {
        if (i < MOD) {
            inverse[i] = MOD - static_cast<ll>(MOD / i) * inverse[MOD % i] % MOD;
        } else {
            inverse[i] = inverse[i % MOD];
        }
        res = (res + mMod * inverse[i]) % MOD;
    }

    ll denominator = (m + 1) % MOD;
    ll factor = (static_cast<ll>(n) * modPow(denominator, MOD - 2) + 1) % MOD;
    res = res * factor % MOD;

    cout << res << '\n';
    return 0;
}

